	FResolvedRuleSet MakeAdversaryRules()
	{
		FResolvedRuleSet Rules = MakeRules();
		FAdversaryMissionRule Mission;
		Mission.Identity.RuleId = TEXT("mission.glass-tide-survey");
		Mission.DisplayName = TEXT("Glass Tide Survey");
		Mission.ContactRuleId = TEXT("contact.skimmer");
		Mission.TargetRegionId = TEXT("region.cascadia");
		Mission.OriginLongitudeMilliDegrees = -165000;
		Mission.OriginLatitudeMilliDegrees = 42000;
		Mission.DestinationLongitudeMilliDegrees = -118000;
		Mission.DestinationLatitudeMilliDegrees = 49000;
		Mission.IntervalHours = 24;
		Mission.MinimumEscalation = 1;
		Mission.SelectionWeight = 1;
		Mission.PressureOnEscape = 15;
		Mission.PressureReductionOnDestroyed = 5;
		Mission.ScorePenaltyOnEscape = 75;
		Mission.FundingPenaltyOnEscape = 20000;
		Rules.AdversaryMissions.Add(Mission.Identity.RuleId, Mission);
		return Rules;
	}

	FResolvedRuleSet MakeLandingAdversaryRules()
	{
		FResolvedRuleSet Rules = MakeAdversaryRules();
		FAdversaryMissionRule& Mission = Rules.AdversaryMissions.FindChecked(TEXT("mission.glass-tide-survey"));
		Mission.bCreatesLandingSiteOnArrival = true;
		Mission.LandingSiteLifetimeHours = 36;
		Mission.LandingSiteThreatBonus = 2;

		const FTacticalMissionRule& Wreckage = Rules.TacticalMissions.FindChecked(TEXT("tactical.test-recovery"));
		FTacticalMissionRule Landing = Wreckage;
		Landing.Identity.RuleId = TEXT("tactical.test-landing-denial");
		Landing.DisplayName = TEXT("Test Landing Denial");
		Landing.SiteType = ETacticalSiteType::Landing;
		Landing.ObjectiveId = TEXT("objective.test-break-anchor");
		Landing.ObjectiveType = ETacticalObjectiveType::Disrupt;
		Landing.ObjectiveRequiredInteractions = 3;
		Landing.BaseEnemyCount = 4;
		Rules.TacticalMissions.Add(Landing.Identity.RuleId, Landing);
		return Rules;
	}

	FResolvedRuleSet MakeBranchingAdversaryRules()
	{
		FResolvedRuleSet Rules = MakeAdversaryRules();
		FAdversaryPlanRule Plan;
		Plan.Identity.RuleId = TEXT("plan.mirror-rain");
		Plan.DisplayName = TEXT("Mirror Rain Pattern");
		Plan.OpeningMissionRuleId = TEXT("mission.glass-tide-survey");
		Rules.AdversaryPlans.Add(Plan.Identity.RuleId, Plan);

		FAdversaryMissionRule& Opening = Rules.AdversaryMissions.FindChecked(Plan.OpeningMissionRuleId);
		Opening.PlanId = Plan.Identity.RuleId;
		Opening.PlanStage = 1;
		Opening.EscapeBranchMissionRuleId = TEXT("mission.nightglass-raid");
		Opening.ThwartBranchMissionRuleId = TEXT("mission.saffron-incursion");

		FAdversaryMissionRule EscapeBranch = Opening;
		EscapeBranch.Identity.RuleId = TEXT("mission.nightglass-raid");
		EscapeBranch.DisplayName = TEXT("Nightglass Raid");
		EscapeBranch.PlanStage = 2;
		EscapeBranch.EscapeBranchMissionRuleId = NAME_None;
		EscapeBranch.ThwartBranchMissionRuleId = NAME_None;
		EscapeBranch.bTargetsPlayerBase = true;
		EscapeBranch.IntervalHours = 30;
		EscapeBranch.MinimumEscalation = 2;
		EscapeBranch.BaseFacilityDamage = 110;
		EscapeBranch.BaseFacilitiesHit = 2;
		Rules.AdversaryMissions.Add(EscapeBranch.Identity.RuleId, EscapeBranch);

		FAdversaryMissionRule ThwartBranch = Opening;
		ThwartBranch.Identity.RuleId = TEXT("mission.saffron-incursion");
		ThwartBranch.DisplayName = TEXT("Saffron Incursion");
		ThwartBranch.PlanStage = 2;
		ThwartBranch.EscapeBranchMissionRuleId = NAME_None;
		ThwartBranch.ThwartBranchMissionRuleId = NAME_None;
		ThwartBranch.TargetRegionId = TEXT("region.western-pacific");
		ThwartBranch.DestinationLongitudeMilliDegrees = 110000;
		ThwartBranch.DestinationLatitudeMilliDegrees = 35000;
		ThwartBranch.IntervalHours = 42;
		ThwartBranch.MinimumEscalation = 2;
		Rules.AdversaryMissions.Add(ThwartBranch.Identity.RuleId, ThwartBranch);
		return Rules;
	}

