	FStrategicSimulationConfig MakeConfig()
	{
		FStrategicSimulationConfig Config;
		Config.BaseEstablishmentCost = 10000;
		Config.DefaultScientistCapacity = 10;
		Config.DefaultEngineerCapacity = 8;
		return Config;
	}

	FEstablishBaseCommand MakeBaseCommand(const int64 ExpectedSequence = 0)
	{
		FEstablishBaseCommand Command;
		Command.ExpectedSequence = ExpectedSequence;
		Command.BaseId = TestBaseId;
		Command.Name = TEXT("Northwatch");
		Command.RegionId = TEXT("region.cascadia");
		Command.LongitudeMilliDegrees = -123120;
		Command.LatitudeMilliDegrees = 49280;
		Command.StartingFacilities.Add(TEXT("facility.operations-hub"));
		return Command;
	}

	FCampaignState MakeStateWithBase()
	{
		FCampaignState State;
		State.Funds = 20000;
		FStrategicCommandService::Execute(State, MakeRules(), MakeConfig(), MakeBaseCommand());
		return State;
	}

	FPersonnelState& AddTestPersonnel(
		FCampaignState& State,
		const FGuid PersonnelId = FGuid(141, 142, 143, 144),
		const FString& DisplayName = TEXT("Mara Voss"))
	{
		FPersonnelState& Person = State.Personnel.AddDefaulted_GetRef();
		Person.PersonnelId = PersonnelId;
		Person.DisplayName = DisplayName;
		Person.RoleId = TEXT("role.field-agent");
		Person.BaseId = TestBaseId;
		Person.MaxHealth = 55;
		Person.CurrentHealth = 55;
		Person.Accuracy = 50;
		Person.Resolve = 51;
		Person.Mobility = 52;
		Person.Strength = 53;
		return Person;
	}

	void AddTestFlightDeck(FCampaignState& State)
	{
		FBaseFacilityState& FlightDeck = State.Bases[0].Facilities.AddDefaulted_GetRef();
		FlightDeck.InstanceId = FGuid(217, 218, 219, 220);
		FlightDeck.FacilityId = TEXT("facility.flight-deck");
		FlightDeck.GridX = 1;
		FlightDeck.GridY = 0;
	}

