	TestFalse(TEXT("Intact vision blocker hides the cell behind it"), BlockedVisibility.IsCellVisible(3, 0));
	TestFalse(TEXT("Intact vision blocker hides an adversary behind it"), BlockedVisibility.IsUnitVisible(HiddenUnit.UnitId));
	VisibilityBattle.Cells[2].CurrentIntegrity = 0;
